<section class="site-page-heading"><div class="container"><p class="site-kicker"><a href="/">首页</a><?php foreach ($breadcrumb as $crumb): ?> / <a href="<?= \FangdaysCMS\Cms\View::e(\FangdaysCMS\Cms\View::categoryLink($crumb)) ?>"><?= \FangdaysCMS\Cms\View::e($crumb['name']) ?></a><?php endforeach; ?></p><h1><?= \FangdaysCMS\Cms\View::e($category['name']) ?></h1></div></section>
<div class="container py-5">
  <?php if ($child_categories): ?><section class="mb-4" aria-label="子栏目"><h2 class="h5 mb-3">子栏目</h2><div class="row"><?php foreach ($child_categories as $child): ?><div class="col-md-4 mb-3"><a class="site-category d-block h-100 p-4" href="<?= \FangdaysCMS\Cms\View::e(\FangdaysCMS\Cms\View::categoryLink($child)) ?>"><h3 class="h5 mb-0"><?= \FangdaysCMS\Cms\View::e($child['name']) ?> →</h3></a></div><?php endforeach; ?></div></section><?php endif; ?>
  <?php if ($filter_fields): ?><section class="card p-3 mb-4" aria-label="扩展字段筛选"><h2 class="h5 mb-3">筛选内容</h2><form method="get" action="/category/<?= \FangdaysCMS\Cms\View::e($category['slug']) ?>"><div class="form-row">
    <?php foreach ($filter_fields as $field): ?><div class="col-md-4 mb-3"><label for="filter-<?= (int) $field['id'] ?>"><?= \FangdaysCMS\Cms\View::e($field['label']) ?></label><select class="form-control" id="filter-<?= (int) $field['id'] ?>" name="<?= \FangdaysCMS\Cms\View::e($field['name']) ?>"><option value="">全部</option><?php foreach ($field['options'] as $option): ?><option value="<?= \FangdaysCMS\Cms\View::e($option) ?>" <?= $field['current'] === $option ? 'selected' : '' ?>><?= \FangdaysCMS\Cms\View::e($option) ?></option><?php endforeach; ?></select></div><?php endforeach; ?>
  </div><button class="btn btn-success" type="submit">筛选</button> <a class="btn btn-link" href="/category/<?= \FangdaysCMS\Cms\View::e($category['slug']) ?>">清除条件</a></form><?php if ($filter_invalid): ?><p class="text-warning mt-3 mb-0">筛选选项无效，请重新选择。</p><?php endif; ?></section><?php endif; ?>
  <section aria-label="栏目文章"><h2 class="h5 mb-3">文章</h2><div class="row">
  <?php foreach ($posts as $post): ?><div class="col-md-6 mb-4"><article class="card h-100 site-card"><?php if ($post['cover_path']): ?><a href="<?= \FangdaysCMS\Cms\View::e(\FangdaysCMS\Cms\View::postLink($post)) ?>"><img class="site-cover" src="<?= \FangdaysCMS\Cms\View::e($post['cover_path']) ?>" alt="" loading="lazy"></a><?php endif; ?><div class="card-body"><p class="small text-muted"><?= date('Y-m-d', (int) $post['published_at']) ?></p><h2 class="h5"><a href="<?= \FangdaysCMS\Cms\View::e(\FangdaysCMS\Cms\View::postLink($post)) ?>"<?= $post['title_color'] !== '' ? ' style="color:' . \FangdaysCMS\Cms\View::e($post['title_color']) . '"' : '' ?>><?= \FangdaysCMS\Cms\View::e($post['title']) ?></a></h2><?php if ($post['subtitle'] !== ''): ?><p class="small mb-2"><?= \FangdaysCMS\Cms\View::e($post['subtitle']) ?></p><?php endif; ?><p class="text-muted mb-0"><?= \FangdaysCMS\Cms\View::e($post['seo_description'] ?: \FangdaysCMS\Cms\RichText::summary($post['body'], $post['body_format'], 100)) ?></p></div></article></div><?php endforeach; ?>
  <?php if (! $posts): ?><p class="col-12 text-muted"><?= $filter_invalid ? '请调整筛选条件。' : ($filter_params ? '没有符合条件的已发布文章。' : '该栏目还没有已发布的文章。') ?></p><?php endif; ?>
</div></section><?= \FangdaysCMS\Cms\View::pagination($page, $total_pages, '/category/' . rawurlencode($category['slug']), $filter_params) ?></div>
